export type Asset = {
	id: string;
	filename: string;
	originalName: string;
	mimeType: string;
	size: number;
	url: string;
	folderId?: string;
	alt?: string;
	tenantId?: string | null;
	createdAt: Date;
	/** Mutation version used for authoritative compare-and-swap checks. */
	updatedAt?: Date;
};

export type Folder = {
	id: string;
	name: string;
	parentId?: string;
	tenantId?: string | null;
	createdAt: Date;
	/** Mutation version used for authoritative compare-and-swap checks. */
	updatedAt?: Date;
};

export interface SerializedAsset
	extends Omit<Asset, "createdAt" | "updatedAt"> {
	createdAt: string;
}

export interface SerializedFolder
	extends Omit<Folder, "createdAt" | "updatedAt"> {
	createdAt: string;
}

import { z } from "zod";

export const AssetListQuerySchema = z.object({
	folderId: z.string().optional(),
	mimeType: z.string().optional(),
	query: z
		.string()
		.max(200)
		.transform((value) => value.trim() || undefined)
		.optional(),
	offset: z.coerce.number().int().min(0).optional(),
	limit: z.coerce.number().int().min(1).max(100).optional(),
});

/** HTTP-only sentinel that distinguishes root folders from an unfiltered list. */
export const ROOT_FOLDER_QUERY_VALUE = "__root__";

export const FolderListQuerySchema = z
	.object({
		parentId: z.string().optional(),
	})
	.transform(({ parentId }) => ({
		parentId: parentId === ROOT_FOLDER_QUERY_VALUE ? null : parentId,
	}));

export const createAssetSchema = z.object({
	filename: z.string().min(1),
	originalName: z.string().min(1),
	mimeType: z.string().min(1),
	// Allow 0 for URL-registered assets where size is unknown at registration time.
	size: z.number().int().min(0),
	url: z.httpUrl(),
	folderId: z.string().optional(),
	alt: z.string().optional(),
});

export const updateAssetSchema = z.object({
	alt: z.string().optional(),
	folderId: z.string().nullable().optional(),
});

export const createFolderSchema = z.object({
	name: z.string().min(1),
	parentId: z.string().optional(),
});

export const uploadTokenRequestSchema = z.object({
	filename: z.string().min(1),
	mimeType: z.string().min(1),
	size: z.number().int().positive(),
	folderId: z.string().optional(),
});

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";

const tenantFact = { tenantId: z.string().optional() };
const folderFact = {
	folderId: z.string(),
	parentId: z.string().optional(),
	...tenantFact,
};
const assetFact = {
	assetId: z.string(),
	folderId: z.string().optional(),
	mimeType: z.string(),
	...tenantFact,
};

/** Browser-safe, schema-backed permissions published by Media. */
export const mediaPermissions = definePermissions("media", {
	library: {
		/** Read the server-scoped asset/folder collection used by the library and picker. */
		read: permission(),
	},
	asset: {
		/** Receive, present, or select one asset from an authorized collection read. */
		read: permission(z.object(assetFact)),
		/**
		 * Start or finish an upload. `callback` is reserved for a provider-verified
		 * completion callback whose context was bound into the server-issued token.
		 */
		upload: permission(
			z.object({
				phase: z.enum(["initialize", "direct", "finalize", "callback"]),
				folderId: z.string().optional(),
				/** Omitted by pre-file browser gates; server operations always derive it. */
				mimeType: z.string().optional(),
				...tenantFact,
			}),
		),
		/** Update a server-resolved asset. */
		update: permission(
			z.object({
				...assetFact,
				/** `null` means moving to root; omitted means the folder is unchanged. */
				targetFolderId: z.string().nullable().optional(),
			}),
		),
		/** Delete a server-resolved asset and its storage object. */
		delete: permission(z.object(assetFact)),
	},
	folder: {
		/** Create a folder beneath a server-resolved parent. */
		create: permission(
			z.object({
				parentId: z.string().optional(),
				...tenantFact,
			}),
		),
		/** Delete a server-resolved folder after authorizing every folder in its subtree. */
		delete: permission(z.object(folderFact)),
	},
});

import { useDeleteAsset } from "@btst/stack/plugins/media/client/hooks";
import type { SerializedAsset } from "../../../types";
import { cn } from "@/lib/utils";
import { File, Check, Copy, Trash2 } from "lucide-react";
import { isImage, formatBytes } from "./utils";
import {
	PermissionAccess,
	useNotify,
	useStack,
	useTranslate,
} from "@btst/stack/context";
import { AssetPreviewButton } from "./asset-preview-button";
import { mediaPermissions } from "../../../permissions";

export function AssetCard({
	asset,
	onToggle,
	selected = false,
	onDelete,
}: {
	asset: SerializedAsset;
	selected?: boolean;
	onToggle?: () => void;
	onDelete?: (id: string) => void | Promise<void>;
}) {
	const t = useTranslate();
	const notify = useNotify();
	const { mutateAsync: deleteAsset } = useDeleteAsset();
	const { api, router } = useStack();
	const ImageComponent = router?.Image;
	const imageAsset = isImage(asset.mimeType);
	const selectable = typeof onToggle === "function";
	const facts = {
		assetId: asset.id,
		...(asset.folderId ? { folderId: asset.folderId } : {}),
		mimeType: asset.mimeType,
	};

	const copyUrl = async () => {
		let fullUrl: string;
		try {
			fullUrl = new URL(asset.url, api?.baseURL).href;
		} catch {
			fullUrl = asset.url;
		}
		try {
			await navigator.clipboard.writeText(fullUrl);
			notify.success(t("media.toasts.copySuccess", "URL copied"));
		} catch {
			notify.error(t("media.toasts.copyError", "Failed to copy URL"));
		}
	};

	const handleDelete = async () => {
		if (onDelete) {
			await onDelete(asset.id);
			return;
		}

		if (
			confirm(
				t("media.assets.deleteNamedConfirm", 'Delete "{{filename}}"?', {
					filename: asset.originalName,
				}),
			)
		) {
			try {
				await deleteAsset(asset.id);
				notify.success(t("media.toasts.deleteSuccess", "Asset deleted"));
			} catch (error) {
				notify.error(
					error instanceof Error
						? error.message
						: t("media.toasts.deleteError", "Delete failed"),
				);
			}
		}
	};

	return (
		<PermissionAccess
			permission={mediaPermissions.asset.read(facts)}
			legacyPermission={{
				resource: "media:asset",
				action: "read",
				params: { id: asset.id },
			}}
		>
			<div
				role={selectable ? "button" : undefined}
				tabIndex={selectable ? 0 : undefined}
				data-testid="media-asset-item"
				onClick={onToggle}
				onKeyDown={(e) => {
					if (selectable && (e.key === "Enter" || e.key === " ")) {
						e.preventDefault();
						onToggle();
					}
				}}
				className={cn(
					"group relative cursor-pointer rounded-md border bg-muted/30 p-1 transition-all hover:border-ring hover:shadow-sm",
					!selectable && "cursor-default",
					selected && "border-ring ring-1 ring-ring",
				)}
			>
				{/* Thumbnail */}
				<div className="flex h-28 items-center justify-center overflow-hidden rounded bg-muted">
					{imageAsset ? (
						ImageComponent ? (
							<ImageComponent
								src={asset.url}
								alt={asset.alt || asset.originalName}
								className="h-full w-full object-cover"
								width={160}
								height={80}
							/>
						) : (
							<img
								src={asset.url}
								alt={asset.alt || asset.originalName}
								className="h-full w-full object-cover"
								loading="lazy"
							/>
						)
					) : (
						<File className="size-8 text-muted-foreground" />
					)}
				</div>

				{/* Name + size */}
				<div className="mt-1 px-0.5">
					<p
						className="truncate text-xs font-medium leading-tight"
						title={asset.originalName}
					>
						{asset.originalName}
					</p>
					<p className="text-[10px] text-muted-foreground">
						{formatBytes(asset.size)}
					</p>
				</div>

				{/* Selection indicator */}
				{selected && (
					<div className="absolute right-1 top-1 rounded-full bg-primary p-0.5 text-primary-foreground">
						<Check className="size-3" />
					</div>
				)}

				<div className="absolute right-1 top-1 hidden gap-1 group-hover:flex">
					{api?.baseURL ? (
						<button
							type="button"
							title={t("media.actions.copyUrl", "Copy URL")}
							onClick={(e) => {
								e.stopPropagation();
								void copyUrl();
							}}
							className="rounded bg-background/80 p-0.5 shadow hover:bg-background"
						>
							<Copy className="size-3" />
						</button>
					) : null}
					{imageAsset ? (
						<AssetPreviewButton
							asset={asset}
							className="rounded bg-background/80 p-0.5 shadow hover:bg-background"
						/>
					) : null}
					<PermissionAccess
						permission={mediaPermissions.asset.delete(facts)}
						legacyPermission={{
							resource: "media:asset",
							action: "delete",
							params: { id: asset.id },
						}}
					>
						<button
							type="button"
							title={t("media.actions.delete", "Delete")}
							onClick={(e) => {
								e.stopPropagation();
								void handleDelete();
							}}
							className="rounded bg-destructive/80 p-0.5 text-white hover:bg-destructive"
						>
							<Trash2 className="size-3" />
						</button>
					</PermissionAccess>
				</div>
			</div>
		</PermissionAccess>
	);
}

"use client";

import { useState } from "react";
import {
	Dialog,
	DialogClose,
	DialogContent,
	DialogHeader,
	DialogTitle,
} from "@/components/ui/dialog";
import { Eye, X } from "lucide-react";
import type { SerializedAsset } from "../../../types";
import { useTranslate } from "@btst/stack/context";

export function AssetPreviewButton({
	asset,
	className,
}: {
	asset: SerializedAsset;
	className: string;
}) {
	const t = useTranslate();
	const [open, setOpen] = useState(false);

	return (
		<>
			<button
				type="button"
				title={t("media.actions.preview", "Preview")}
				aria-label={t("media.assets.previewLabel", "Preview {{filename}}", {
					filename: asset.originalName,
				})}
				onClick={(event) => {
					event.stopPropagation();
					setOpen(true);
				}}
				className={className}
			>
				<Eye className="size-3" />
			</button>

			<Dialog open={open} onOpenChange={setOpen}>
				<DialogContent
					showCloseButton={false}
					className="h-screen w-screen max-w-none border-0 bg-black/95 p-4 shadow-none sm:max-w-none sm:rounded-none sm:p-6"
				>
					<DialogHeader className="sr-only">
						<DialogTitle>{asset.alt || asset.originalName}</DialogTitle>
					</DialogHeader>

					<DialogClose
						className="absolute right-4 top-4 z-10 rounded bg-black/60 p-2 text-white transition hover:bg-black/80"
						aria-label={t("media.actions.closePreview", "Close preview")}
					>
						<X className="size-4" />
					</DialogClose>

					<div className="h-full w-full overflow-auto">
						<div className="flex min-h-full w-full items-start justify-center">
							<img
								src={asset.url}
								alt={asset.alt || asset.originalName}
								className="block h-auto w-auto max-w-none"
							/>
						</div>
					</div>
				</DialogContent>
			</Dialog>
		</>
	);
}

import { useEffect, useState, useRef } from "react";
import { useAssets } from "@btst/stack/plugins/media/client/hooks";
import type { SerializedAsset } from "../../../types";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Loader2, Search, X, Image } from "lucide-react";
import { AssetCard } from "./asset-card";
import { matchesAccept } from "./utils";
import { useTranslate } from "@btst/stack/context";

export function BrowseTab({
	folderId,
	selected = [],
	accept,
	onToggle,
	onDelete,
	emptyMessage,
	search: controlledSearch,
	searchQuery,
	onSearchChange,
}: {
	folderId: string | null;
	selected?: SerializedAsset[];
	accept?: string[];
	onToggle?: (asset: SerializedAsset) => void;
	onDelete?: (id: string) => void | Promise<void>;
	emptyMessage?: string;
	/** Optional controlled input value used by the standalone library page. */
	search?: string;
	/** Debounced query value; defaults to BrowseTab's local debounce. */
	searchQuery?: string;
	onSearchChange?: (value: string) => void;
}) {
	const t = useTranslate();
	const [localSearch, setLocalSearch] = useState("");
	const [debouncedSearch, setDebouncedSearch] = useState("");
	const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
	const selectable = typeof onToggle === "function";
	const search = controlledSearch ?? localSearch;
	const effectiveQuery = searchQuery ?? debouncedSearch;

	useEffect(
		() => () => {
			if (debounceRef.current) clearTimeout(debounceRef.current);
		},
		[],
	);

	const handleSearch = (v: string) => {
		if (onSearchChange) {
			onSearchChange(v);
			return;
		}
		setLocalSearch(v);
		if (debounceRef.current) clearTimeout(debounceRef.current);
		debounceRef.current = setTimeout(() => setDebouncedSearch(v), 300);
	};

	const { data, fetchNextPage, hasNextPage, isFetchingNextPage, isLoading } =
		useAssets({
			folderId: folderId ?? undefined,
			query: effectiveQuery || undefined,
			limit: 40,
		});

	const allAssets = data?.pages.flatMap((p) => p.items) ?? [];
	const filtered = accept
		? allAssets.filter((a) => matchesAccept(a.mimeType, accept))
		: allAssets;

	return (
		<div className="flex h-full min-h-0 flex-col gap-2">
			<div className="relative">
				<Search className="absolute left-2 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
				<Input
					value={search}
					onChange={(e) => handleSearch(e.target.value)}
					maxLength={200}
					placeholder={t("media.assets.searchPlaceholder", "Search files…")}
					className="h-8 pl-7 text-sm"
				/>
				{search && (
					<button
						type="button"
						title={t("media.actions.clearSearch", "Clear search")}
						onClick={() => {
							if (onSearchChange) onSearchChange("");
							else setLocalSearch("");
							setDebouncedSearch("");
						}}
						className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
					>
						<X className="size-3.5" />
					</button>
				)}
			</div>

			{isLoading ? (
				<div className="flex flex-1 items-center justify-center">
					<Loader2 className="size-6 animate-spin text-muted-foreground" />
				</div>
			) : filtered.length === 0 ? (
				<div className="flex flex-1 flex-col items-center justify-center gap-2 text-sm text-muted-foreground">
					<Image className="size-8" />
					<p>{emptyMessage ?? t("media.assets.empty", "No files found")}</p>
				</div>
			) : (
				<div className="flex-1 overflow-y-auto overscroll-contain">
					<div className="grid grid-cols-2 gap-2 pb-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5">
						{filtered.map((asset) => (
							<AssetCard
								key={asset.id}
								asset={asset}
								selected={selected.some((s) => s.id === asset.id)}
								onToggle={selectable ? () => onToggle(asset) : undefined}
								onDelete={onDelete}
							/>
						))}
					</div>
					{hasNextPage && (
						<div className="flex justify-center py-2">
							<Button
								variant="ghost"
								size="sm"
								onClick={() => fetchNextPage()}
								disabled={isFetchingNextPage}
							>
								{isFetchingNextPage ? (
									<Loader2 className="mr-1 size-3 animate-spin" />
								) : null}
								{t("media.actions.loadMore", "Load more")}
							</Button>
						</div>
					)}
				</div>
			)}
		</div>
	);
}

import { useMemo, useState } from "react";
import {
	useFolders,
	useDeleteFolder,
	useCreateFolderForm,
} from "@btst/stack/plugins/media/client/hooks";
import type { SerializedFolder } from "../../../types";
import { FolderPlus } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Check, Folder, Trash2, ChevronRight, FolderOpen } from "lucide-react";
import { cn } from "@/lib/utils";
import { PermissionAccess, useNotify, useTranslate } from "@btst/stack/context";
import { mediaPermissions } from "../../../permissions";

export function FolderTree({
	selectedId,
	onSelect,
}: {
	selectedId: string | null;
	onSelect: (id: string | null) => void;
}) {
	const t = useTranslate();
	const notify = useNotify();
	const { data: foldersRaw = [] } = useFolders();
	const folders = foldersRaw as import("../../../types").SerializedFolder[];
	const { foldersById, foldersByParent } = useMemo(() => {
		const byId = new Map<string, SerializedFolder>();
		const byParent = new Map<string | null, SerializedFolder[]>();
		for (const folder of folders) {
			byId.set(folder.id, folder);
			const parentId = folder.parentId ?? null;
			const siblings = byParent.get(parentId) ?? [];
			siblings.push(folder);
			byParent.set(parentId, siblings);
		}
		return { foldersById: byId, foldersByParent: byParent };
	}, [folders]);
	const rootFolders = foldersByParent.get(null) ?? [];
	const selectedFolder = selectedId ? foldersById.get(selectedId) : undefined;
	const [newFolderName, setNewFolderName] = useState("");
	const [isCreating, setIsCreating] = useState(false);
	const { mutateAsync: deleteFolder } = useDeleteFolder();
	const createPermission = mediaPermissions.folder.create({
		...(selectedId ? { parentId: selectedId } : {}),
	});
	const createFolderForm = useCreateFolderForm({
		parentId: selectedId ?? undefined,
		onSuccess: () => {
			setNewFolderName("");
			setIsCreating(false);
		},
	});

	const handleCreateFolder = async () => {
		const name = newFolderName.trim();
		if (!name) return;
		await createFolderForm.submit({ name });
	};

	const handleDeleteFolder = async () => {
		if (!selectedId) return;
		if (
			!confirm(
				t(
					"media.folders.deleteConfirm",
					"Delete this folder? Assets inside will be unaffected.",
				),
			)
		)
			return;
		try {
			await deleteFolder(selectedId);
			onSelect(null);
			notify.success(t("media.toasts.folderDeleteSuccess", "Folder deleted"));
		} catch (error) {
			notify.error(
				error instanceof Error
					? error.message
					: t("media.toasts.folderDeleteError", "Failed to delete folder"),
			);
		}
	};

	return (
		<div className="flex h-full min-h-0 flex-col">
			<div className="flex items-center justify-between px-2 py-2">
				<span className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
					{t("media.folders.title", "Folders")}
				</span>
				<PermissionAccess
					permission={createPermission}
					legacyPermission={{ resource: "media:folder", action: "create" }}
				>
					<button
						type="button"
						title={t("media.folders.new", "New folder")}
						onClick={() => setIsCreating((v) => !v)}
						className="rounded p-0.5 hover:bg-muted"
					>
						<FolderPlus className="size-3.5 text-muted-foreground" />
					</button>
				</PermissionAccess>
			</div>

			{isCreating && (
				<PermissionAccess
					permission={createPermission}
					legacyPermission={{ resource: "media:folder", action: "create" }}
				>
					<div className="flex gap-1 px-2 pb-1">
						<Input
							autoFocus
							value={newFolderName}
							onChange={(e) => {
								setNewFolderName(e.target.value);
								createFolderForm.clearErrors();
							}}
							placeholder={t("media.folders.namePlaceholder", "Folder name")}
							className="h-6 text-xs"
							onKeyDown={(e) => {
								if (e.key === "Enter") void handleCreateFolder();
								if (e.key === "Escape") setIsCreating(false);
							}}
						/>
						<button
							type="button"
							onClick={handleCreateFolder}
							disabled={createFolderForm.isSubmitting || !newFolderName.trim()}
							title={t("media.folders.create", "Create folder")}
							className="rounded px-1 py-0.5 text-xs hover:bg-muted"
						>
							<Check className="size-3" />
						</button>
						{createFolderForm.fieldErrors.name ? (
							<p className="text-xs text-destructive">
								{String(createFolderForm.fieldErrors.name)}
							</p>
						) : null}
					</div>
				</PermissionAccess>
			)}

			<div className="flex-1 overflow-y-auto overscroll-contain">
				{/* All assets (root) */}
				<button
					type="button"
					onClick={() => onSelect(null)}
					className={cn(
						"flex w-full items-center gap-1.5 rounded px-2 py-1 text-left text-sm hover:bg-muted",
						selectedId === null && "bg-muted font-medium",
					)}
				>
					<span className="size-3" />
					<Folder className="size-3.5 shrink-0 text-muted-foreground" />
					<span className="truncate">
						{t("media.folders.allFiles", "All files")}
					</span>
				</button>

				{rootFolders.map((folder) => (
					<FolderTreeItem
						key={folder.id}
						folder={folder}
						foldersByParent={foldersByParent}
						selectedId={selectedId}
						onSelect={onSelect}
					/>
				))}
			</div>

			{selectedId && selectedFolder && (
				<PermissionAccess
					permission={mediaPermissions.folder.delete({
						folderId: selectedId,
						...(selectedFolder.parentId
							? { parentId: selectedFolder.parentId }
							: {}),
					})}
					legacyPermission={{
						resource: "media:folder",
						action: "delete",
						params: {
							id: selectedId,
							...(selectedFolder.parentId
								? { parentId: selectedFolder.parentId }
								: {}),
						},
					}}
				>
					<div className="border-t px-2 py-1">
						<button
							type="button"
							onClick={() => void handleDeleteFolder()}
							className="flex items-center gap-1 text-xs text-destructive hover:underline"
						>
							<Trash2 className="size-3" />
							{t("media.folders.delete", "Delete folder")}
						</button>
					</div>
				</PermissionAccess>
			)}
		</div>
	);
}

export function FolderTreeItem({
	folder,
	foldersByParent,
	selectedId,
	onSelect,
	depth = 0,
}: {
	folder: SerializedFolder;
	foldersByParent: ReadonlyMap<string | null, readonly SerializedFolder[]>;
	selectedId: string | null;
	onSelect: (id: string | null) => void;
	depth?: number;
}) {
	const [expanded, setExpanded] = useState(false);
	const children = foldersByParent.get(folder.id) ?? [];

	return (
		<div>
			<button
				type="button"
				onClick={() => {
					onSelect(folder.id);
					setExpanded((v) => !v);
				}}
				className={cn(
					"flex w-full items-center gap-1.5 rounded px-2 py-1 text-left text-sm hover:bg-muted",
					selectedId === folder.id && "bg-muted font-medium",
				)}
				style={{ paddingLeft: `${8 + depth * 12}px` }}
			>
				{children.length > 0 ? (
					<ChevronRight
						className={cn(
							"size-3 shrink-0 transition-transform",
							expanded && "rotate-90",
						)}
					/>
				) : (
					<span className="size-3" />
				)}
				{expanded ? (
					<FolderOpen className="size-3.5 shrink-0 text-amber-500" />
				) : (
					<Folder className="size-3.5 shrink-0 text-amber-500" />
				)}
				<span className="truncate">{folder.name}</span>
			</button>
			{expanded &&
				children.map((child) => (
					<FolderTreeItem
						key={child.id}
						folder={child}
						foldersByParent={foldersByParent}
						selectedId={selectedId}
						onSelect={onSelect}
						depth={depth + 1}
					/>
				))}
		</div>
	);
}

"use client";
import { useState, type ReactNode } from "react";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import {
	Tabs,
	TabsContent,
	TabsList,
	TabsTrigger,
} from "@/components/ui/tabs";
import { Image, Upload, Link, X } from "lucide-react";
import type { SerializedAsset } from "../../../types";
import { FolderTree } from "./folder-tree";
import { BrowseTab } from "./browse-tab";
import { UploadTab } from "./upload-tab";
import { UrlTab } from "./url-tab";
import {
	PermissionAccess,
	usePluginOverrides,
	useStack,
	useTranslate,
} from "@btst/stack/context";
import { mediaPermissions } from "../../../permissions";
import type { MediaPluginOverrides } from "../../overrides";
import {
	MediaFinalizePermissionCheck,
	MediaUploadPermissionCheck,
} from "../upload-permission-check";

export interface MediaPickerProps {
	/**
	 * Element that triggers opening the picker. Required.
	 */
	trigger: ReactNode;
	/**
	 * Called when the user confirms their selection.
	 */
	onSelect: (assets: SerializedAsset[]) => void;
	/**
	 * Allow multiple selection.
	 * @default false
	 */
	multiple?: boolean;
	/**
	 * Filter displayed assets by MIME type prefix (e.g. "image/").
	 */
	accept?: string[];
}

function AssetSelectionAccess({
	assets,
	children,
}: {
	assets: readonly SerializedAsset[];
	children: ReactNode;
}) {
	const [asset, ...rest] = assets;
	if (!asset) return children;
	return (
		<PermissionAccess
			permission={mediaPermissions.asset.read({
				assetId: asset.id,
				...(asset.folderId ? { folderId: asset.folderId } : {}),
				mimeType: asset.mimeType,
			})}
			legacyPermission={{
				resource: "media:asset",
				action: "read",
				params: { id: asset.id },
			}}
		>
			<AssetSelectionAccess assets={rest}>{children}</AssetSelectionAccess>
		</PermissionAccess>
	);
}

/**
 * MediaPicker — a Popover-based media browser.
 *
 * Reads API and router config from `StackProvider`.
 *
 * @example
 * ```tsx
 * <MediaPicker
 *   trigger={<Button size="sm">Browse media</Button>}
 *   accept={["image/*"]}
 *   onSelect={(assets) => form.setValue("image", assets[0].url)}
 * />
 * ```
 */
export function MediaPicker({
	trigger,
	onSelect,
	multiple = false,
	accept,
}: MediaPickerProps) {
	const t = useTranslate();
	const { uploadMode = "direct" } =
		usePluginOverrides<MediaPluginOverrides>("media");
	const [open, setOpen] = useState(false);
	const [selectedFolder, setSelectedFolder] = useState<string | null>(null);
	const [selectedAssets, setSelectedAssets] = useState<SerializedAsset[]>([]);
	const [activeTab, setActiveTab] = useState<"browse" | "upload" | "url">(
		"browse",
	);

	const handleClose = () => {
		setOpen(false);
		setSelectedAssets([]);
	};

	const handleConfirm = () => {
		if (selectedAssets.length === 0) return;
		// Copy selection before clearing; defer onSelect so the popover has time
		// to start its close animation before any parent state updates that might
		// unmount this component (e.g. CMSFileUpload hiding when previewUrl is set).
		const toSelect = [...selectedAssets];
		handleClose();
		setTimeout(() => onSelect(toSelect), 0);
	};

	const handleToggleAsset = (asset: SerializedAsset) => {
		if (multiple) {
			setSelectedAssets((prev) =>
				prev.some((a) => a.id === asset.id)
					? prev.filter((a) => a.id !== asset.id)
					: [...prev, asset],
			);
		} else {
			setSelectedAssets([asset]);
		}
	};

	const handleUploaded = (asset: SerializedAsset) => {
		if (multiple) {
			setSelectedAssets((prev) => [...prev, asset]);
		} else {
			setSelectedAssets([asset]);
			setActiveTab("browse");
		}
	};

	const handleUrlRegistered = (asset: SerializedAsset) => {
		// URL registration grants upload-finalize permission, not read/select
		// permission. Send the result through the same asset.read-gated confirmation
		// path as browsed and uploaded assets.
		handleUploaded(asset);
		setActiveTab("browse");
	};

	return (
		<PermissionAccess
			permission={mediaPermissions.library.read()}
			legacyPermission={{ resource: "media:asset", action: "read" }}
		>
			<MediaUploadPermissionCheck
				mode={uploadMode}
				folderId={selectedFolder ?? undefined}
			>
				{({ can: canUpload, isPending, error }) => {
					if (error) throw error;
					const uploadAllowed = canUpload && !isPending;
					return (
						<MediaFinalizePermissionCheck
							folderId={selectedFolder ?? undefined}
						>
							{({ can: canFinalize, isPending: finalizePending, error }) => {
								if (error) throw error;
								const finalizeAllowed = canFinalize && !finalizePending;
								const visibleTab =
									(activeTab === "upload" && !uploadAllowed) ||
									(activeTab === "url" && !finalizeAllowed)
										? "browse"
										: activeTab;
								return (
									<Popover
										open={open}
										onOpenChange={(v) => {
											if (!v) handleClose();
											else setOpen(true);
										}}
									>
										<PopoverTrigger asChild>{trigger}</PopoverTrigger>
										<PopoverContent
											className="w-[calc(100vw-1rem)] max-w-[calc(100vw-1rem)] overflow-hidden p-0 sm:w-[820px]"
											align="start"
											sideOffset={8}
											collisionPadding={8}
											style={{
												maxWidth: "min(820px, calc(100vw - 1rem))",
												height: "min(640px, calc(100dvh - 2rem))",
											}}
										>
											<div className="flex h-full flex-col overflow-hidden rounded-md">
												{/* Header */}
												<div className="flex items-center justify-between border-b px-3 py-2">
													<span className="text-sm font-semibold">
														{t("media.picker.title", "Media Library")}
													</span>
													<button
														type="button"
														aria-label={t("media.actions.close", "Close")}
														onClick={handleClose}
														className="rounded p-0.5 hover:bg-muted"
													>
														<X className="size-4" />
													</button>
												</div>

												{/* Body */}
												<div className="flex min-h-0 flex-1 flex-col md:flex-row">
													{/* Folder sidebar */}
													<div className="max-h-40 w-full shrink-0 overflow-hidden border-b bg-muted/20 md:max-h-none md:w-44 md:border-b-0 md:border-r">
														<FolderTree
															selectedId={selectedFolder}
															onSelect={setSelectedFolder}
														/>
													</div>

													{/* Main panel */}
													<div className="flex min-w-0 flex-1 flex-col p-3 overflow-y-hidden">
														<Tabs
															value={visibleTab}
															onValueChange={(v) => setActiveTab(v as any)}
															className="flex flex-1 flex-col min-h-0"
														>
															<TabsList
																className={`grid h-auto w-full shrink-0 ${uploadAllowed && finalizeAllowed ? "grid-cols-3" : uploadAllowed || finalizeAllowed ? "grid-cols-2" : "grid-cols-1"} md:flex md:w-fit`}
															>
																<TabsTrigger
																	value="browse"
																	className="h-8 px-2 text-xs md:h-6 md:px-3"
																>
																	<Image className="mr-1 size-3" />
																	{t("media.tabs.browse", "Browse")}
																</TabsTrigger>
																{uploadAllowed ? (
																	<TabsTrigger
																		value="upload"
																		className="h-8 px-2 text-xs md:h-6 md:px-3"
																	>
																		<Upload className="mr-1 size-3" />
																		{t("media.tabs.upload", "Upload")}
																	</TabsTrigger>
																) : null}
																{finalizeAllowed ? (
																	<TabsTrigger
																		value="url"
																		className="h-8 px-2 text-xs md:h-6 md:px-3"
																	>
																		<Link className="mr-1 size-3" />
																		{t("media.tabs.url", "URL")}
																	</TabsTrigger>
																) : null}
															</TabsList>

															<div className="mt-2 min-h-0 flex-1">
																<TabsContent
																	value="browse"
																	className="m-0 h-full min-h-0 data-[state=active]:flex data-[state=active]:flex-col"
																>
																	<BrowseTab
																		folderId={selectedFolder}
																		selected={selectedAssets}
																		accept={accept}
																		onToggle={handleToggleAsset}
																	/>
																</TabsContent>
																{uploadAllowed ? (
																	<TabsContent
																		value="upload"
																		className="m-0 h-full min-h-0 data-[state=active]:flex data-[state=active]:flex-col"
																	>
																		<UploadTab
																			folderId={selectedFolder}
																			accept={accept}
																			onUploaded={handleUploaded}
																		/>
																	</TabsContent>
																) : null}
																{finalizeAllowed ? (
																	<TabsContent
																		value="url"
																		className="m-0 h-full min-h-0 data-[state=active]:flex data-[state=active]:flex-col"
																	>
																		<UrlTab
																			folderId={selectedFolder}
																			onRegistered={handleUrlRegistered}
																		/>
																	</TabsContent>
																) : null}
															</div>
														</Tabs>
													</div>
												</div>

												{/* Footer */}
												<div className="flex flex-col gap-2 border-t px-3 py-2 sm:flex-row sm:items-center sm:justify-between">
													<span className="text-xs text-muted-foreground">
														{selectedAssets.length > 0
															? t(
																	"media.picker.selected",
																	"{{count}} selected",
																	{
																		count: selectedAssets.length,
																	},
																)
															: t(
																	"media.picker.selectHint",
																	"Click a file to select it",
																)}
													</span>
													<div className="flex w-full gap-2 sm:w-auto">
														<Button
															type="button"
															variant="ghost"
															size="sm"
															onClick={handleClose}
															className="flex-1 sm:flex-none"
														>
															{t("media.actions.cancel", "Cancel")}
														</Button>
														<AssetSelectionAccess assets={selectedAssets}>
															<Button
																type="button"
																size="sm"
																data-testid="media-select-button"
																onClick={handleConfirm}
																disabled={selectedAssets.length === 0}
																className="flex-1 sm:flex-none"
															>
																{multiple
																	? t(
																			"media.actions.selectMany",
																			"Select ({{count}})",
																			{
																				count: selectedAssets.length,
																			},
																		)
																	: t("media.actions.select", "Select")}
															</Button>
														</AssetSelectionAccess>
													</div>
												</div>
											</div>
										</PopoverContent>
									</Popover>
								);
							}}
						</MediaFinalizePermissionCheck>
					);
				}}
			</MediaUploadPermissionCheck>
		</PermissionAccess>
	);
}

/**
