export function LibraryPage() {
	const t = useTranslate();
	const notify = useNotify();
	const overrides = usePluginOverrides<
		MediaPluginOverrides,
		Partial<MediaPluginOverrides>
	>("media", {});
	useRouteLifecycle({
		routeName: "library",
		context: {
			path: "/media",
			isSSR: typeof window === "undefined",
		},
		overrides,
	});

	const [{ folder, q: search }, setListState] = useListState("media-library", {
		folder: { type: "string", default: "" },
		q: { type: "string", default: "", history: "replace" },
	} as const satisfies ListStateSchema);
	const selectedFolder = folder || null;
	const [searchInput, setSearchInput] = useState(search);
	const lastSyncedSearch = useRef(search);

	useEffect(() => {
		if (search !== lastSyncedSearch.current) {
			lastSyncedSearch.current = search;
			setSearchInput(search);
		}
	}, [search]);

	useEffect(() => {
		if (searchInput === search) return;
		const timeout = setTimeout(() => {
			lastSyncedSearch.current = searchInput;
			setListState({ q: searchInput });
		}, 300);
		return () => clearTimeout(timeout);
	}, [searchInput, search, setListState]);

	const setSelectedFolder = useCallback(
		(id: string | null) => setListState({ folder: id ?? "" }),
		[setListState],
	);
	const [dragging, setDragging] = useState(false);
	const fileInputRef = useRef<HTMLInputElement>(null);
	const { mutateAsync: uploadAsset, isPending: isUploading } = useUploadAsset();
	const { mutateAsync: deleteAsset } = useDeleteAsset();
	const handleUpload = useCallback(
		async (files: FileList | File[]) => {
			const arr = Array.from(files);
			for (const file of arr) {
				try {
					await uploadAsset({ file, folderId: selectedFolder ?? undefined });
					notify.success(
						t("media.toasts.uploadSuccess", "Uploaded {{filename}}", {
							filename: file.name,
						}),
					);
				} catch (err) {
					notify.error(
						err instanceof Error
							? err.message
							: t("media.toasts.uploadError", "Upload failed"),
					);
				}
			}
		},
		[notify, selectedFolder, t, uploadAsset],
	);

	const handleDelete = async (id: string) => {
		if (!confirm(t("media.assets.deleteConfirm", "Delete this asset?"))) return;
		try {
			await deleteAsset(id);
			notify.success(t("media.toasts.deleteSuccess", "Asset deleted"));
		} catch (err) {
			notify.error(
				err instanceof Error
					? err.message
					: t("media.toasts.deleteError", "Delete failed"),
			);
		}
	};

	return (
		<MediaUploadPermissionCheck
			mode={overrides.uploadMode ?? "direct"}
			folderId={selectedFolder ?? undefined}
		>
			{({ can: canUpload, isPending, error }) => {
				if (error) throw error;
				const uploadAllowed = canUpload && !isPending;
				return (
					<div className="flex h-[calc(100dvh-4rem)] flex-col overflow-hidden md:flex-row">
						<div className="max-h-48 shrink-0 overflow-hidden border-b bg-muted/20 md:h-full md:max-h-none md:w-52 md:border-b-0 md:border-r">
							<FolderTree
								selectedId={selectedFolder}
								onSelect={setSelectedFolder}
							/>
						</div>

						<div
							className={cn(
								"relative flex flex-1 flex-col overflow-hidden border-t md:border-t-0",
								dragging && "ring-2 ring-inset ring-ring",
							)}
							onDragOver={(e) => {
								if (!uploadAllowed) return;
								e.preventDefault();
								setDragging(true);
							}}
							onDragLeave={() => setDragging(false)}
							onDrop={(e) => {
								if (!uploadAllowed) return;
								e.preventDefault();
								setDragging(false);
								void handleUpload(e.dataTransfer.files);
							}}
						>
							{/* Toolbar */}
							<div className="flex flex-col gap-3 border-b px-4 py-3 sm:flex-row sm:items-center sm:justify-end">
								{uploadAllowed ? (
									<>
										<Button
											size="sm"
											onClick={() => fileInputRef.current?.click()}
											disabled={isUploading}
											className="w-full sm:w-auto"
										>
											{isUploading ? (
												<Loader2 className="mr-2 size-3.5 animate-spin" />
											) : (
												<Upload className="mr-2 size-3.5" />
											)}
											{t("media.actions.upload", "Upload")}
										</Button>
										<input
											ref={fileInputRef}
											type="file"
											multiple
											className="hidden"
											onChange={(e) =>
												e.target.files && handleUpload(e.target.files)
											}
										/>
									</>
								) : null}
							</div>

							{/* Drop overlay */}
							{dragging && uploadAllowed && (
								<div className="pointer-events-none absolute inset-0 z-10 flex items-center justify-center bg-background/80">
									<div className="rounded-lg border-2 border-dashed border-ring p-8 text-center">
										<Upload className="mx-auto mb-2 size-10 text-ring" />
										<p className="font-medium">
											{t("media.upload.dropFiles", "Drop files to upload")}
										</p>
									</div>
								</div>
							)}

							<div className="flex-1 min-h-0 p-3 sm:p-4">
								<BrowseTab
									folderId={selectedFolder}
									search={searchInput}
									searchQuery={search}
									onSearchChange={setSearchInput}
									onDelete={handleDelete}
									emptyMessage={t(
										"media.assets.emptyLibrary",
										"No files yet. Drag & drop or click Upload.",
									)}
								/>
							</div>
						</div>
					</div>
				);
			}}
		</MediaUploadPermissionCheck>
	);
}

"use client";
import { lazy } from "react";
import type { FallbackProps } from "react-error-boundary";
import { usePluginOverrides } from "@btst/stack/context";
import { ComposedRoute } from "@btst/stack/client/components";
import type { MediaPluginOverrides } from "../../overrides";
import { Loader2 } from "lucide-react";
import { mediaPermissions } from "../../../permissions";

const LibraryPage = lazy(() =>
	import("./library-page.internal").then((m) => ({ default: m.LibraryPage })),
);

function LibraryLoading() {
	return (
		<div className="flex h-96 items-center justify-center">
			<Loader2 className="size-8 animate-spin text-muted-foreground" />
		</div>
	);
}

function LibraryError({ error }: FallbackProps) {
	const message = error instanceof Error ? error.message : String(error);
	return (
		<div className="flex h-96 items-center justify-center p-8 text-destructive">
			<p className="text-sm">{message}</p>
		</div>
	);
}

export function LibraryPageComponent() {
	usePluginOverrides<MediaPluginOverrides>("media");
	return (
		<ComposedRoute
			path="/media"
			permission={mediaPermissions.library.read()}
			legacyPermission={{ resource: "media:asset", action: "read" }}
			PageComponent={LibraryPage}
			ErrorComponent={LibraryError}
			LoadingComponent={LibraryLoading}
			NotFoundComponent={() => null}
			onError={(error) => console.error("[btst/media] Library error:", error)}
		/>
	);
}

"use client";

import {
	PermissionCheck,
	type PermissionCheckState,
} from "@btst/stack/context";
import type { ReactNode } from "react";
import { mediaPermissions } from "../../permissions";
import type { MediaUploadMode } from "../overrides";

function UploadPhaseCheck({
	phases,
	folderId,
	children,
}: {
	phases: readonly ("initialize" | "direct" | "finalize")[];
	folderId?: string;
	children: (state: PermissionCheckState) => ReactNode;
}) {
	const [phase, ...rest] = phases;
	if (!phase) return children({ can: true, isPending: false });
	return (
		<PermissionCheck
			permission={mediaPermissions.asset.upload({
				phase,
				...(folderId ? { folderId } : {}),
			})}
			legacyPermission={{ resource: "media:asset", action: "create" }}
		>
			{(state) => {
				if (state.error || state.isPending || !state.can)
					return children(state);
				return (
					<UploadPhaseCheck phases={rest} folderId={folderId}>
						{children}
					</UploadPhaseCheck>
				);
			}}
		</PermissionCheck>
	);
}

/** Gate a browser upload flow through every server phase it will invoke. */
export function MediaUploadPermissionCheck({
	mode,
	folderId,
	children,
}: {
	mode: MediaUploadMode;
	folderId?: string;
	children: (state: PermissionCheckState) => ReactNode;
}) {
	return (
		<UploadPhaseCheck
			phases={mode === "direct" ? ["direct"] : ["initialize", "finalize"]}
			folderId={folderId}
		>
			{children}
		</UploadPhaseCheck>
	);
}

/** Gate URL registration through the exact finalization descriptor. */
export function MediaFinalizePermissionCheck({
	folderId,
	children,
}: {
	folderId?: string;
	children: (state: PermissionCheckState) => ReactNode;
}) {
	return (
		<UploadPhaseCheck phases={["finalize"]} folderId={folderId}>
			{children}
		</UploadPhaseCheck>
	);
}

import type { QueryClient } from "@tanstack/react-query";
import type { ImageCompressionOptions } from "./utils/image-compression";

/**
 * Upload mode — must match the storage adapter configured in mediaBackendPlugin.
 * - `"direct"` — local filesystem adapter, files are uploaded via `POST /media/upload`
 * - `"s3"` — AWS S3 / R2 / MinIO, the client fetches a presigned token then PUTs directly to S3
 * - `"vercel-blob"` — Vercel Blob, uses the `@vercel/blob/client` SDK for direct upload
 */
export type MediaUploadMode = "direct" | "s3" | "vercel-blob";

/**
 * Overridable components and functions for the Media plugin.
 *
 * External consumers provide these when registering the media client plugin
 * via the StackProvider overrides.
 */
export interface MediaPluginOverrides {
	/**
	 * React Query client — used by the MediaPicker to cache and fetch assets.
	 */
	queryClient: QueryClient;

	/**
	 * Upload mode — must match the storageAdapter configured in mediaBackendPlugin.
	 * @default "direct"
	 */
	uploadMode?: MediaUploadMode;

	/**
	 * Optional headers to pass with API requests (e.g., for SSR auth).
	 */
	headers?: HeadersInit;

	/**
	 * Client-side image compression applied before upload via the Canvas API.
	 *
	 * Images are scaled down to fit within `maxWidth` × `maxHeight` (preserving
	 * aspect ratio) and re-encoded at `quality`. SVG and GIF files are always
	 * passed through unchanged.
	 *
	 * Set to `false` to disable compression entirely.
	 *
	 * @default { maxWidth: 2048, maxHeight: 2048, quality: 0.85 }
	 */
	imageCompression?: ImageCompressionOptions | false;

	// ============ Lifecycle Hooks ============

	/**
	 * Called when a media route is rendered.
	 */
	onRouteRender?: (
		routeName: string,
		context: MediaRouteContext,
	) => void | Promise<void>;

	/**
	 * Called when a media route encounters an error.
	 */
	onRouteError?: (
		routeName: string,
		error: Error,
		context: MediaRouteContext,
	) => void | Promise<void>;
}

export interface MediaRouteContext {
	/** Current route path */
	path: string;
	/** Route parameters */
	params?: Record<string, string>;
	/** Whether rendering on server (true) or client (false) */
	isSSR: boolean;
	[key: string]: unknown;
}

"use client";

import type { SerializedAsset } from "../types";
import type { MediaUploadMode } from "./overrides";
import { compressImage } from "./utils/image-compression";
import type { ImageCompressionOptions } from "./utils/image-compression";

export interface MediaUploadClientConfig {
	apiBaseURL: string;
	apiBasePath: string;
	headers?: HeadersInit;
	uploadMode?: MediaUploadMode;
	imageCompression?: ImageCompressionOptions | false;
}

export interface UploadAssetInput {
	file: File;
	folderId?: string;
}

const DEFAULT_IMAGE_COMPRESSION = {
	maxWidth: 2048,
	maxHeight: 2048,
	quality: 0.85,
} as const;

/**
 * Upload an asset using the media plugin's configured storage mode.
 *
 * Use this in non-React contexts like editor `uploadImage` callbacks. React
 * components should usually prefer `useUploadAsset()`, which wraps this helper
 * and handles cache invalidation.
 */
export async function uploadAsset(
	config: MediaUploadClientConfig,
	input: UploadAssetInput,
): Promise<SerializedAsset> {
	const {
		apiBaseURL,
		apiBasePath,
		headers,
		uploadMode = "direct",
		imageCompression,
	} = config;
	const { file, folderId } = input;

	const processedFile =
		imageCompression === false
			? file
			: await compressImage(
					file,
					imageCompression ?? DEFAULT_IMAGE_COMPRESSION,
				);

	const base = `${apiBaseURL}${apiBasePath}`;
	const headersObj = new Headers(headers as HeadersInit | undefined);

	if (uploadMode === "direct") {
		const formData = new FormData();
		formData.append("file", processedFile);
		if (folderId) formData.append("folderId", folderId);

		const res = await fetch(`${base}/media/upload`, {
			method: "POST",
			headers: headersObj,
			body: formData,
		});
		if (!res.ok) {
			const err = await res.json().catch(() => ({ message: res.statusText }));
			throw new Error(err.message ?? "Upload failed");
		}
		return res.json();
	}

	if (uploadMode === "s3") {
		const tokenRes = await fetch(`${base}/media/upload/token`, {
			method: "POST",
			headers: {
				...Object.fromEntries(headersObj.entries()),
				"Content-Type": "application/json",
			},
			body: JSON.stringify({
				filename: processedFile.name,
				mimeType: processedFile.type,
				size: processedFile.size,
				folderId,
			}),
		});
		if (!tokenRes.ok) {
			const err = await tokenRes
				.json()
				.catch(() => ({ message: tokenRes.statusText }));
			throw new Error(err.message ?? "Failed to get upload token");
		}

		const token = (await tokenRes.json()) as {
			type: "presigned-url";
			payload: {
				uploadUrl: string;
				publicUrl: string;
				key: string;
				method: "PUT";
				headers: Record<string, string>;
			};
		};

		const putRes = await fetch(token.payload.uploadUrl, {
			method: "PUT",
			headers: token.payload.headers,
			body: processedFile,
		});
		if (!putRes.ok) throw new Error("Failed to upload to S3");

		const assetRes = await fetch(`${base}/media/assets`, {
			method: "POST",
			headers: {
				...Object.fromEntries(headersObj.entries()),
				"Content-Type": "application/json",
			},
			body: JSON.stringify({
				filename: processedFile.name,
				originalName: file.name,
				mimeType: processedFile.type,
				size: processedFile.size,
				url: token.payload.publicUrl,
				folderId,
			}),
		});
		if (!assetRes.ok) {
			const err = await assetRes
				.json()
				.catch(() => ({ message: assetRes.statusText }));
			throw new Error(err.message ?? "Failed to register asset");
		}
		return assetRes.json();
	}

	if (uploadMode === "vercel-blob") {
		// Dynamic import keeps @vercel/blob/client optional.
		const { upload } = await import("@vercel/blob/client");
		const blob = await upload(processedFile.name, processedFile, {
			access: "public",
			handleUploadUrl: `${base}/media/upload/vercel-blob`,
			clientPayload: JSON.stringify({
				mimeType: processedFile.type,
				size: processedFile.size,
				...(folderId ? { folderId } : {}),
			}),
		});

		const assetRes = await fetch(`${base}/media/assets`, {
			method: "POST",
			headers: {
				...Object.fromEntries(headersObj.entries()),
				"Content-Type": "application/json",
			},
			body: JSON.stringify({
				filename: processedFile.name,
				originalName: file.name,
				mimeType: processedFile.type,
				size: processedFile.size,
				url: blob.url,
				folderId,
			}),
		});
		if (!assetRes.ok) {
			const err = await assetRes
				.json()
				.catch(() => ({ message: assetRes.statusText }));
			throw new Error(err.message ?? "Failed to register asset");
		}
		return assetRes.json();
	}

	throw new Error(`Unknown uploadMode: ${uploadMode}`);
}

/**
 * Canvas-based client-side image compression.
 *
 * Skips SVG and GIF (vector data / animation would be lost on a canvas round-trip).
 * All other image/* types are scaled down to fit within maxWidth × maxHeight
 * (preserving aspect ratio) and re-encoded at the configured quality.
 */

export interface ImageCompressionOptions {
	/**
	 * Maximum width in pixels. Images wider than this are scaled down.
	 * @default 2048
	 */
	maxWidth?: number;

	/**
	 * Maximum height in pixels. Images taller than this are scaled down.
	 * @default 2048
	 */
	maxHeight?: number;

	/**
	 * Encoding quality (0–1). Applies to JPEG and WebP.
	 * @default 0.85
	 */
	quality?: number;

	/**
	 * Output MIME type. Defaults to the source image's MIME type.
	 * Set to `"image/webp"` for better compression at the cost of format change.
	 */
	outputFormat?: string;
}

function loadImage(file: File): Promise<HTMLImageElement> {
	return new Promise((resolve, reject) => {
		const url = URL.createObjectURL(file);
		const img = new Image();
		img.onload = () => {
			URL.revokeObjectURL(url);
			resolve(img);
		};
		img.onerror = () => {
			URL.revokeObjectURL(url);
			reject(new Error(`Failed to load image: ${file.name}`));
		};
		img.src = url;
	});
}

const SKIP_TYPES = new Set(["image/svg+xml", "image/gif"]);

/**
 * Compresses an image file client-side using the Canvas API.
 *
 * Returns the original file unchanged if:
 * - The file is not an image
 * - The MIME type is SVG or GIF (would lose vector data / animation)
 * - The browser does not support canvas (SSR guard)
 */
export async function compressImage(
	file: File,
	options: ImageCompressionOptions = {},
): Promise<File> {
	if (!file.type.startsWith("image/") || SKIP_TYPES.has(file.type)) {
		return file;
	}

	// SSR guard — canvas is only available in the browser
	if (typeof document === "undefined") return file;

	const {
		maxWidth = 2048,
		maxHeight = 2048,
		quality = 0.85,
		outputFormat,
	} = options;

	const img = await loadImage(file);

	let { width, height } = img;

	const needsResize = width > maxWidth || height > maxHeight;
	const needsFormatChange =
		outputFormat !== undefined && outputFormat !== file.type;

	// Skip canvas entirely if the image is already within the limits and no
	// format conversion is needed — re-encoding a small image can make it larger.
	if (!needsResize && !needsFormatChange) return file;

	// Scale down proportionally if either dimension exceeds the max
	if (needsResize) {
		const ratio = Math.min(maxWidth / width, maxHeight / height);
		width = Math.round(width * ratio);
		height = Math.round(height * ratio);
	}

	const canvas = document.createElement("canvas");
	canvas.width = width;
	canvas.height = height;

	const ctx = canvas.getContext("2d");
	if (!ctx) return file;

	ctx.drawImage(img, 0, 0, width, height);

	const mimeType = outputFormat ?? file.type;

	return new Promise<File>((resolve, reject) => {
		canvas.toBlob(
			(blob) => {
				if (!blob) {
					reject(new Error("canvas.toBlob returned null"));
					return;
				}

				// Preserve the original filename, updating extension only if
				// the output format changed from the source.
				let name = file.name;
				if (outputFormat && outputFormat !== file.type) {
					const ext = outputFormat.split("/")[1] ?? "jpg";
					name = name.replace(/\.[^.]+$/, `.${ext}`);
				}

				resolve(new File([blob], name, { type: mimeType }));
			},
			mimeType,
			quality,
		);
	});
}

"use client";

import { useEffect } from "react";

/**
 * Base route context interface that plugins can extend
 */
export interface BaseRouteContext {
	/** Current route path */
	path: string;
	/** Route parameters (e.g., { slug: "my-post" }) */
	params?: Record<string, string>;
	/** Whether rendering on server (true) or client (false) */
	isSSR: boolean;
	/** Additional context properties */
	[key: string]: unknown;
}

/**
 * Minimum interface required for route lifecycle hooks
 * Plugin overrides should implement these optional hooks
 */
export interface RouteLifecycleOverrides<TContext extends BaseRouteContext> {
	/** Called when a route is rendered */
	onRouteRender?: (
		routeName: string,
		context: TContext,
	) => void | Promise<void>;
	/** Called when a route encounters an error */
	onRouteError?: (
		routeName: string,
		error: Error,
		context: TContext,
	) => void | Promise<void>;
}

/**
 * Hook to handle route lifecycle events
 * - Calls onRouteRender on mount
 * - Handles errors with onRouteError
 *
 * @example
 * ```tsx
 * const overrides = usePluginOverrides<MyPluginOverrides>("myPlugin");
 *
 * useRouteLifecycle({
 *   routeName: "dashboard",
 *   context: { path: "/dashboard", isSSR: typeof window === "undefined" },
 *   overrides,
 * });
 * ```
 */
export function useRouteLifecycle<
	TContext extends BaseRouteContext,
	TOverrides extends RouteLifecycleOverrides<TContext>,
>({
	routeName,
	context,
	overrides,
}: {
	routeName: string;
	context: TContext;
	overrides: TOverrides;
}) {
	// Lifecycle hook - runs on mount
	useEffect(() => {
		if (overrides.onRouteRender) {
			try {
				const result = overrides.onRouteRender(routeName, context);
				if (result instanceof Promise) {
					result.catch((error) => {
						// If onRouteRender throws, call onRouteError
						if (overrides.onRouteError) {
							overrides.onRouteError(routeName, error, context);
						}
					});
				}
			} catch (error) {
				// If onRouteRender throws, call onRouteError
				if (overrides.onRouteError) {
					overrides.onRouteError(routeName, error as Error, context);
				}
			}
		}
	}, [routeName, overrides, context]);
}
